type Line = { desc: string; amount: number };
class Invoice {
  constructor(private lines: Line[], private customer?: string, private notes?: string) {}
}
class InvoiceBuilder {
  private lines: Line[] = [];
  private customer?: string;
  private notes?: string;
  addLine(line: Line) { this.lines.push(line); return this; }
  withCustomer(c: string) { this.customer = c; return this; }
  withNotes(n: string) { this.notes = n; return this; }
  build() { return new Invoice(this.lines, this.customer, this.notes); }
}
const invoice = new InvoiceBuilder().addLine({ desc: 'Item', amount: 100 }).withCustomer('ACME').withNotes('Urgent').build();

