// Version A: domain object holds construction responsibilities
class ProductA {
  constructor(
    public name: string,
    public price: number,
    public color?: string,
    public warrantyMonths?: number,
    public tags: string[] = []
  ) {}
  static createWithOptions(opts: Partial<ProductA> & { name: string; price: number }) {
    // complex assembly logic inside domain class
    return new ProductA(opts.name, opts.price, opts.color, opts.warrantyMonths, opts.tags || []);
  }
}

// Version B: separate configurator handles stepwise assembly
class ProductConfigurator {
  private name!: string;
  private price!: number;
  private color?: string;
  private warrantyMonths?: number;
  private tags: string[] = [];
  setName(n: string) { this.name = n; return this; }
  setPrice(p: number) { this.price = p; return this; }
  setColor(c: string) { this.color = c; return this; }
  setWarranty(m: number) { this.warrantyMonths = m; return this; }
  addTag(t: string) { this.tags.push(t); return this; }
  build() { return new ProductA(this.name, this.price, this.color, this.warrantyMonths, this.tags); }
}
